PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;

INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q01','7','Assinale a alternativa correta, conforme o texto.

Contexto:
Crônica tem esta vantagem: não obriga ao paletó-e-gravata do editorialista, forçado a definir uma posição correta diante dos grandes problemas; não exige de quem a faz o nervosismo saltitante do repórter, responsável pela apuração do fato na hora mesma em que ele acontece; dispensa a especialização suada em economia, finanças, política nacional e internacional, esporte, religião e o mais que imaginar se possa. Sei bem que existem o cronista político, o esportivo, o religioso, o econômico, etc., mas a crônica de que estou falando é aquela que não precisa entender de nada ao falar de tudo. Não se exige do cronista geral a informação ou os comentários precisos que cobramos dos outros. O que lhe pedimos é uma espécie de loucura mansa, que desenvolva determinado ponto de vista não ortodoxo e não trivial, e desperte em nós a inclinação para o jogo da fantasia, o absurdo e a vadiação de espírito. Claro que ele deve ser um cara confiável, ainda na divagação. Não se compreende, ou não compreendo, cronista faccioso, que sirva a interesse pessoal ou de grupo, porque a crônica é território livre da imaginação, empenhada em circular entre os acontecimentos do dia, sem procurar influir neles. Fazer mais do que isto seria pretensão descabida de sua parte. Ele sabe que seu prazo de atuação é limitado: minutos no café da manhã ou à espera do coletivo. Carlos Drummond de Andrade – “Ciao”, in Shopping News – City News.','assinale a alternativa correta conforme o texto contexto cronica tem esta vantagem nao obriga ao paleto e gravata do editorialista forcado a definir uma posicao correta diante dos grandes problemas nao exige de quem a faz o nervosismo saltitante do reporter responsavel pela apuracao do fato na hora mesma em que ele acontece dispensa a especializacao suada em economia financas politica nacional e internacional esporte religiao e o mais que imaginar se possa sei bem que existem o cronista politico o esportivo o religioso o economico etc mas a cronica de que estou falando e aquela que nao precisa entender de nada ao falar de tudo nao se exige do cronista geral a informacao ou os comentarios precisos que cobramos dos outros o que lhe pedimos e uma especie de loucura mansa que desenvolva determinado ponto de vista nao ortodoxo e nao trivial e desperte em nos a inclinacao para o jogo da fantasia o absurdo e a vadiacao de espirito claro que ele deve ser um cara confiavel ainda na divagacao nao se compreende ou nao compreendo cronista faccioso que sirva a interesse pessoal ou de grupo porque a cronica e territorio livre da imaginacao empenhada em circular entre os acontecimentos do dia sem procurar influir neles fazer mais do que isto seria pretensao descabida de sua parte ele sabe que seu prazo de atuacao e limitado minutos no cafe da manha ou a espera do coletivo carlos drummond de andrade ciao in shopping news city news','["As palavras “ortodoxo” e “trivial” são sinônimas.","A expressão “pretensão descabida” significa modéstia sem cabimento.","Para o autor, a crônica geral é lida minutos antes do café ou quando se está esperando o ônibus.","O editor de um jornal precisa sempre trajar paletó e gravata ao contrário do cronista.","A crônica especialista, como a esportiva, exige de seu autor imaginação livre e divagações para escrever seu posicionamento."]',2,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',1,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q02','7','Assinale a alternativa que traduz o significado da expressão “nervosismo saltitante do repórter” no texto.','assinale a alternativa que traduz o significado da expressao nervosismo saltitante do reporter no texto','["Exatidão da notícia.","Criatividade do repórter.","Sensacionalismo da notícia.","Tristeza por não conseguir o furo de reportagem.","Ansiedade pela necessidade de ser rápido."]',4,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',2,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q03','7','Assinale a alternativa correta, considerando o significado contextual das expressões.','assinale a alternativa correta considerando o significado contextual das expressoes','["jogo da fantasia: distração irreal","comentários precisos: ser apropriado ao tema sobre o que escreve","loucura mansa: insanidade que não precisa de tratamento","vadiação de espírito: malandragem de intenções","cronista faccioso: escrever crônicas sem parcialidade"]',1,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',3,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q04','7','Considere a frase adaptada do texto e assinale a alternativa correta.','considere a frase adaptada do texto e assinale a alternativa correta','["Contém problemas com a coesão textual na articulação das ideias.","“… a informação” é um termo essencial na frase; é, pois um sujeito simples.","Se trocássemos o termo sublinhado por “os quais” ele concordaria com “outros” e a frase continuaria correta.","A frase “embora o que lhe pedimos é uma espécie de loucura mansa” dá uma ideia aditiva à frase no seu contexto.","A palavra “não” que inicia o texto tem função sintática diferente das duas outras vezes em que aparece, já que se refere a um verbo enquanto que as outras a um adjetivo."]',0,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',4,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q05','7','Sobre a frase “Crônica tem esta vantagem”, assinale a alternativa que apresenta a correta análise morfológica.','sobre a frase cronica tem esta vantagem assinale a alternativa que apresenta a correta analise morfologica','["adjetivo, verbo, pronome possessivo, adjetivo","nome próprio, nome de ação, preposição, adjetivo","substantivo próprio, verbo conjugado, pronome demonstrativo, substantivo","substantivo, verbo, pronome possessivo, adjetivo","substantivo, verbo, pronome demonstrativo, substantivo"]',4,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',5,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q06','7','Assinale a alternativa em que a estruturação frasal (colocada entre parênteses) não alterou o sentido da primeira frase, considerando o texto posto no início da prova.','assinale a alternativa em que a estruturacao frasal colocada entre parenteses nao alterou o sentido da primeira frase considerando o texto posto no inicio da prova','["Ele sabe que seu prazo de atuação é limitado. (Que é limitado seu prazo de atuação ele sabe.)","Não se exige do cronista geral a informação. (Do cronista não se exige a informação geral.)","Não exige de quem a faz o nervosismo saltitante do repórter. (O saltitante nervosismo de quem a faz não exige do repórter.)","Forçado a definir uma posição correta diante dos grandes problemas. (Uma posição correta diante dos corretos grandes problemas, é forçado a decidir.)","Desperte em nós a inclinação para o jogo da fantasia. (A inclinação, em nós, desperte para o jogo da fantasia.)"]',0,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',6,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q07','7','Assinale a alternativa em que a expressão sublinhada é vocativo.','assinale a alternativa em que a expressao sublinhada e vocativo','["Loucura mansa desenvolve seu ponto de vista!","Loucura mansa, desenvolva seu ponto de vista!","A loucura mansa, aquela insensata, desenvolve seu ponto de vista.","Loucura mansa, que desenvolverá seu ponto de vista.","Seu ponto de vista, a loucura mansa que desenvolvia"]',1,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',7,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q08','7','Assinale a alternativa cuja análise sintática do termo sublinhado está correta.','assinale a alternativa cuja analise sintatica do termo sublinhado esta correta','["O que lhe pedimos. Adjunto adverbial","A crônica de que estou falando. Sujeito simples","Ele sabe que seu prazo de atuação é limitado. Adjunto adnominal","Dispensa a especialização suada em economia. Objeto direto","Não precisa entender de nada. Complemento nominal"]',3,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',8,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q09','7','Identifique as afirmativas verdadeiras (V) e falsas (F) sobre as expressões “um cara confiável”, “cronista faccioso”, “a interesse pessoal” e assinale a sequência correta.','identifique as afirmativas verdadeiras v e falsas f sobre as expressoes um cara confiavel cronista faccioso a interesse pessoal e assinale a sequencia correta','["V • V • V • F • F","V • F • V • F • V","F • V • V • F • V","F • V • F • V • F","F • F • F • V • V"]',2,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',9,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q10','7','Assinale a alternativa em que a oração sublinhada conota a ideia de tempo.','assinale a alternativa em que a oracao sublinhada conota a ideia de tempo','["Lia as crônicas conforme eram publicadas.","Para que sejam lidas, as crônicas precisam ser triviais.","Se o tempo que o cronista leva para escrever fosse considerado, teríamos outro olhar para essa profissão.","Porque meu tempo de ler é curto, opto por crônicas menores.","Quando o cronista escreveu sobre política, todos entenderam suas ideias."]',4,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',10,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q11','8','Se ventou no fim de semana, então João e José surfaram. Porém, se choveu no fim de semana, então João não surfou. Ora, sabe-se que João não surfou. Logo, podemos afirmar corretamente que:','se ventou no fim de semana entao joao e jose surfaram porem se choveu no fim de semana entao joao nao surfou ora sabe se que joao nao surfou logo podemos afirmar corretamente que','["Ventou e não choveu no fim de semana.","Não ventou no fim de semana.","Choveu no fim de semana.","Choveu e não ventou no fim de semana.","Não choveu e não ventou no fim de semana."]',1,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',11,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q12','8','Um remador deve escolher dois remos entre 9 disponíveis, sendo que um será usado somente para treinos e o outro somente em competições. De quantas maneiras diferentes ele pode escolher esses dois remos?','um remador deve escolher dois remos entre 9 disponiveis sendo que um sera usado somente para treinos e o outro somente em competicoes de quantas maneiras diferentes ele pode escolher esses dois remos','["Mais de 100","Mais de 90 e menos de 100","Mais de 80 e menos de 90","Mais de 70 e menos de 80","Menos de 70"]',3,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',12,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q13','8','Em uma empresa, uma tarefa extra é sorteada aleatoriamente entre 8 homens e 4 mulheres. A probabilidade de a pessoa sorteada ser mulher é:','em uma empresa uma tarefa extra e sorteada aleatoriamente entre 8 homens e 4 mulheres a probabilidade de a pessoa sorteada ser mulher e','["Maior que 40%.","Maior que 35% e menor que 40%.","Maior que 30% e menor que 35%.","Maior que 25% e menor que 30%.","Menor que 25%."]',2,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',13,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q14','8','Uma escola tem 2 vagas abertas, para as quais se candidatam 50 alunos. A escolha dos alunos para as duas vagas é feita através de um sorteio. Quantos resultados diferentes pode apresentar esse sorteio?','uma escola tem 2 vagas abertas para as quais se candidatam 50 alunos a escolha dos alunos para as duas vagas e feita atraves de um sorteio quantos resultados diferentes pode apresentar esse sorteio','["Mais de 1350","Mais de 1300 e menos de 1350","Mais de 1250 e menos de 1300","Mais de 1200 e menos de 1250","Menos de 1200"]',3,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',14,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q15','8','Na hora do lanche, uma criança tem à sua disposição 5 tipos de bolo e 4 tipos de suco. De quantas maneiras diferentes ela pode elaborar seu lanche, incluindo exatamente 2 tipos de bolo e 2 tipos de suco?','na hora do lanche uma crianca tem a sua disposicao 5 tipos de bolo e 4 tipos de suco de quantas maneiras diferentes ela pode elaborar seu lanche incluindo exatamente 2 tipos de bolo e 2 tipos de suco','["Mais de 59","Mais de 54 e menos de 59","Mais de 49 e menos de 54","Mais de 44 e menos de 49","Menos de 44"]',0,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',15,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q16','2','Imagine que você precisará realizar o arquivamento de documentos em uma pasta denominada manutenção. Os documentos foram datados, respectivamente. Diante desse contexto, qual o tipo de ordem de arquivamento você deve realizar?','imagine que voce precisara realizar o arquivamento de documentos em uma pasta denominada manutencao os documentos foram datados respectivamente diante desse contexto qual o tipo de ordem de arquivamento voce deve realizar','["Temática","Geográfica","Cronológica","Ideográfica","Numérica"]',2,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',16,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q17','3','Mediante os avanços das evoluções tecnológicas, os clientes estão cada vez mais seletivos, exigentes e com um alto grau de expectativas em relação ao atendimento. Analise as afirmativas abaixo ao que se refere à qualidade no atendimento e assinale a alternativa que indica todas as afirmativas corretas.

Contexto:
1. O atendimento ao público constitui a relação interpessoal que envolve o funcionário de uma organização e o destinatário de produtos, ideias ou serviços dessa organização. 2. Considera-se como público toda pessoa que entra em contato com a empresa para solicitar um serviço, falar com um funcionário ou simplesmente pedir uma informação. 3. O atendimento ao público deve ser realizado sempre de forma espontânea, podendo ser usadas expressões de gírias quando da necessidade de se expressar com o cliente. 4. O atendimento prestado com qualidade não se resume apenas ao tratamento ou cortesia, mas significa acrescentar benefícios a produtos e serviços, com o objetivo de superar as expectativas do consumidor. 5. São requisitos básicos para um bom atendimento saber ouvir, conhecer o cliente, perceber suas necessidades e falar com o mesmo de forma adequada.','mediante os avancos das evolucoes tecnologicas os clientes estao cada vez mais seletivos exigentes e com um alto grau de expectativas em relacao ao atendimento analise as afirmativas abaixo ao que se refere a qualidade no atendimento e assinale a alternativa que indica todas as afirmativas corretas contexto 1 o atendimento ao publico constitui a relacao interpessoal que envolve o funcionario de uma organizacao e o destinatario de produtos ideias ou servicos dessa organizacao 2 considera se como publico toda pessoa que entra em contato com a empresa para solicitar um servico falar com um funcionario ou simplesmente pedir uma informacao 3 o atendimento ao publico deve ser realizado sempre de forma espontanea podendo ser usadas expressoes de girias quando da necessidade de se expressar com o cliente 4 o atendimento prestado com qualidade nao se resume apenas ao tratamento ou cortesia mas significa acrescentar beneficios a produtos e servicos com o objetivo de superar as expectativas do consumidor 5 sao requisitos basicos para um bom atendimento saber ouvir conhecer o cliente perceber suas necessidades e falar com o mesmo de forma adequada','["São corretas apenas as afirmativas 2 e 4.","São corretas apenas as afirmativas 4 e 5.","São corretas apenas as afirmativas 1, 2 e 3.","São corretas apenas as afirmativas 2, 3 e 5.","São corretas apenas as afirmativas 1, 2, 4 e 5."]',4,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',17,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
