INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q38','1','No que se refere à ética e à responsabilidade social nas organizações é correto afirmar:','no que se refere a etica e a responsabilidade social nas organizacoes e correto afirmar','["Abrangem somente os aspectos relacionados ao nível individual dos funcionários nas relações entre si.","Abrangem somente os aspectos relacionados aos acionistas.","Abrangem somente os aspectos relacionados aos funcionários e aos acionistas.","Abrangem o ambiente interno das organizações, em especial a relação da administração com os empregados.","Abrangem exclusivamente o ambiente interno das organizações, em especial a relação da administração com os empregados."]',3,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',38,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q39','6','De acordo com a Lei nº 2960/95, considera-se “carreira”:','de acordo com a lei n 2960 95 considera se carreira','["o conjunto de cargos de diferentes classes, escalonados hierarquicamente de acordo com a complexidade e afinidade das atribuições, para progressão dos titulares dos cargos que a integram.","o conjunto de cargos públicos da mesma atividade, atribuições, responsabilidades e níveis de vencimento.","o conjunto dos cargos de um mesmo órgão ou Poder.","o conjunto de tarefas e responsabilidades cometidas ao servidor público.","o vencimento acrescido das vantagens pecuniárias a que o servidor tenha direito, estabelecidas em lei."]',0,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',39,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');
INSERT OR IGNORE INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q40','6','Assinale a alternativa correta de acordo com a Lei nº 2960/95.','assinale a alternativa correta de acordo com a lei n 2960 95','["O limite mínimo de idade para inscrições é de 21 anos completos, na data de encerramento da inscrição nos concursos públicos municipais.","É proibida a acumulação de férias, salvo por absoluta necessidade do serviço e pelo período máximo de 2 anos.","Será concedido adicional noturno correspondente a 20% do valor da hora normal, prestado entre 22 horas e 6 horas do dia seguinte.","A demissão “a bem do serviço público” incompatibiliza o ex-servidor com o serviço público municipal pelo prazo de 15 anos, enquanto a demissão simples o faz pelo prazo de 10 anos.","O servidor em débito com o erário que for demitido, ou que tiver a sua aposentadoria ou disponibilidade cassada, terá o prazo de 30 dias para quitar o débito, sob pena de inscrição em dívida ativa."]',1,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',40,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020');

COMMIT;
